/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_LOSS_EVENT_DETAIL
   anchor      : HUB_LOSS_EVENT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 3 emitted of 3 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_LOSS_EVENT_HK
   hashdiff    : SAT_LOSS_EVENT_DETAIL_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 1 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     LOSS_EVENT_TYPE                        opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_LOSS_EVENT|' || (HUB_LOSS_EVENT_BK__CLAIM_NO))) as HUB_LOSS_EVENT_HK
        , TYPE_OF_LOSS as LOSS_EVENT_TYPE
        , cast(null as varchar) as LOSS_DATE
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CLAIM_NO),'')) is not null
    union all
    select
        md5(upper('HUB_LOSS_EVENT|' || (HUB_LOSS_EVENT_BK__CLAIM_ID))) as HUB_LOSS_EVENT_HK
        , TYPE_OF_LOSS as LOSS_EVENT_TYPE
        , cast(null as varchar) as LOSS_DATE
        , 'BJAZ_HM_INWARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_inward_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_LOSS_EVENT|' || (HUB_LOSS_EVENT_BK__TPA_CLAIM_NO))) as HUB_LOSS_EVENT_HK
        , cast(null as varchar) as LOSS_EVENT_TYPE
        , LOSS_DATE as LOSS_DATE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(TPA_CLAIM_NO),'')) is not null
),

resolved as (
    select
        HUB_LOSS_EVENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOSS_EVENT_TYPE end) as LOSS_EVENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOSS_DATE end) as LOSS_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_LOSS_EVENT_HK
),

hashed as (
    select
        *,
        case when LOSS_EVENT_TYPE is not null or LOSS_DATE is not null
                     then md5(upper(coalesce(cast(LOSS_EVENT_TYPE as varchar), '') || '|' || coalesce(cast(LOSS_DATE as varchar), '')))
                end as SAT_LOSS_EVENT_DETAIL_HASHDIFF
    from resolved
)

select * from hashed
where HUB_LOSS_EVENT_HK is not null
  and SAT_LOSS_EVENT_DETAIL_HASHDIFF is not null
